<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
$user=aw_need_user(true);
header('Cache-Control: private, no-store, max-age=0');
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);
if(!$id || $id<1){http_response_code(400);exit('ID tidak valid');}
$db=aw_db();
$q=$db->prepare('SELECT * FROM aw_applications WHERE id=?');$q->execute([$id]);$a=$q->fetch(PDO::FETCH_ASSOC);
if(!$a){http_response_code(404);exit('Pengajuan tidak ditemukan');}
$q=$db->prepare('SELECT id,requirement_code,original_name,mime_type,size_bytes,created_at FROM aw_attachments WHERE application_id=? ORDER BY id ASC');$q->execute([$id]);$docs=$q->fetchAll(PDO::FETCH_ASSOC);
$q=$db->prepare('SELECT previous_status,new_status,notes,created_at FROM aw_history WHERE application_id=? ORDER BY id ASC');$q->execute([$id]);$history=$q->fetchAll(PDO::FETCH_ASSOC);
$children=json_decode((string)($a['children_json']??'[]'),true);if(!is_array($children))$children=[];
$labels=[];foreach(aw_requirements() as $r)$labels[$r[0]]=$r[1];
foreach($children as $i=>$child){$num=(int)($child['number']??($i+1));if($num>=1&&$num<=10)$labels['child_'.$num]='Dokumen Anak ke-'.$num.' — '.(string)($child['name']??'');}
function aw_print_value($value):string {if($value===null || trim((string)$value)==='')return '<span class="empty">—</span>';return nl2br(aw_e($value));}
function aw_print_field(string $label,$value,bool $wide=false):void {echo '<div class="field'.($wide?' wide':'').'"><div class="field-label">'.aw_e($label).'</div><div class="field-value">'.aw_print_value($value).'</div></div>';}
$statusLabels=['masuk'=>'Masuk','proses'=>'Diproses','revisi'=>'Perlu Perbaikan','selesai'=>'Selesai','ditolak'=>'Ditolak'];
$stamp=date('d/m/Y H:i');
