<script>
(function(){const modal=document.getElementById('photoModal'),img=document.getElementById('modalImage'),title=document.getElementById('modalTitle');function open(el){img.src=el.dataset.src;title.textContent=el.dataset.title;modal.hidden=false;modal.classList.add('active');document.getElementById('closePhoto').focus();}function close(){modal.classList.remove('active');modal.hidden=true;img.removeAttribute('src');}document.querySelectorAll('.thumb[data-src]').forEach(el=>{el.addEventListener('click',()=>open(el));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open(el)}})});document.getElementById('closePhoto').addEventListener('click',close);modal.addEventListener('click',e=>{if(e.target===modal)close();});window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.hidden)close();});})();
</script></body></html>
